fn LineGankCoverPlan::target_bush_v30(&self, player: &PlayerState, data: &OperationData) -> usize
// IR 은 argument promotion 으로 (line:i8, team:usize, pos_idx:u32, cache:&AbstractGameWithCache, ctx:&GameContext) 5개로 풀려 있다.
// 인라인된 것: AbstractGameWithCache::tower(simulation.rs:1822), Option::or/is_none/unwrap/is_some,
//              Position::as_index(entity.rs:580), EntityType::is_tower2(entity.rs:1308),
//              TowerType::is_second_tower(tower.rs:99), map_regions::is_top_side(map_regions.rs:21)

let line = self.line;            // 0=Top 1=Mid 2=Bottom, 그 외 unreachable
let team = <승격된 usize>;       // team >= 2 이면 panic_bounds_check(idx=team, len=2)

// [135] cache.tower(line, team)  — 1차 타워 없으면 2차 타워로 폴백
let tower: Option<&Entity> = match line {
    Top    => cache.top_tower[team]   .or(cache.top_tower2[team]),    // 0x180 .or 0x190
    Mid    => cache.mid_tower[team]   .or(cache.mid_tower2[team]),    // 0x1a0 .or 0x1b0
    Bottom => cache.bottom_tower[team].or(cache.bottom_tower2[team]), // 0x1c0 .or 0x1d0
};

// [136] 타워가 아예 없다(1·2차 모두 파괴) → 라인·팀별 고정 부시
if tower.is_none() {
    return match line {                       // [137]
        Top    => if team == 0 { 2 } else { 16 },   // [138]
        Mid    => if team == 0 { 4 } else { 17 },   // [139]
        Bottom => if team == 0 { 9 } else { 21 },   // [140]
    };
}

let tower = tower.unwrap();                                            // [144]
// [145] 내 챔피언. None 이면 Option::unwrap_failed 패닉(cover.rs:145)
let champ = cache.player_champion[team][player.info.position as usize].unwrap();
// ※ champ 는 Mid 분기에서만 실제로 쓰이지만, unwrap 자체는 모든 라인에서 무조건 실행된다.

let tag = tower.ty_discr;                 // Entity+0x68, 0..13
let is_tower_ty = (tag == 2);             // EntityType::Tower (DISCR_EXACT=2)

match line {

// ───────── Top ─────────
Top => {
    // [149] let EntityType::Tower(info) = tower.ty  else { unreachable!() }  // [160]
    if !is_tower_ty { unreachable!(); }
    let info: &Tower = tower + 0x70;

    // [150] tower.ty.is_tower2()  == (tag==2 && info.ty > TwinB)
    if info.ty /*Entity+0x128*/ > 4 {
        return if team == 0 { 3 } else { 6 };            // [151]
    }
    // [153] info.nearest_enemy(Entity+0x88) 니치태그 != 0
    if info.nearest_enemy.is_some() {
        return if team == 0 { 6 } else { 3 };            // [154]  ← 좌우 뒤집힘
    } else {
        return if team == 0 { 3 } else { 6 };            // [156]
    }
}

// ───────── Mid ─────────  (여기만 unreachable!() 이 없다 — 비-Tower 면 그냥 false 취급)
Mid => {
    // [164] tower.ty.is_tower2()
    let is_t2 = is_tower_ty && (tower.ty.Tower.info.ty > 4);

    // is_top_side(ctx, champ.x, champ.y):
    //   [map_regions.rs:22] let ry = ctx.setting.height(0x12c0) - champ.y(0x668)
    //   [map_regions.rs:24] ry < champ.x(0x660)      ← 맵 반대각선 기준 위/아래
    let top_side = (ctx.setting.height - champ.y) < champ.x;

    if is_t2 {
        // [165] 조건 · [166]/[168] 결과
        return if top_side { if team == 0 { 13 } else { 18 } }   // [168]
               else        { if team == 0 {  8 } else { 12 } };  // [166]
    } else {
        // [171] 팀에 무관 — 이 함수에서 유일하게 team 을 안 쓰는 반환
        return if top_side { 14 } else { 11 };
    }
}

// ───────── Bottom ─────────  (Top 과 구조 동일, 부시 쌍만 {15,20})
Bottom => {
    // [179] let EntityType::Tower(info) = tower.ty  else { unreachable!() }  // [190]
    if !is_tower_ty { unreachable!(); }
    let info: &Tower = tower + 0x70;

    if info.ty > 4 {                                     // [180] is_tower2
        return if team == 0 { 15 } else { 20 };           // [181]
    }
    if info.nearest_enemy.is_some() {                     // [183]
        return if team == 0 { 20 } else { 15 };           // [184]  ← 뒤집힘
    } else {
        return if team == 0 { 15 } else { 20 };           // [186]
    }
}
}

// 정리 — 반환되는 부시 인덱스 전수표
//   라인   상황                                   team0 / team1
//   Top    타워 전멸                                 2 / 16
//   Top    2차타워(TowerType>TwinB)                  3 / 6
//   Top    1차타워 & nearest_enemy=Some              6 / 3
//   Top    1차타워 & nearest_enemy=None              3 / 6
//   Mid    타워 전멸                                 4 / 17
//   Mid    2차타워 & 챔프가 top_side                13 / 18
//   Mid    2차타워 & 챔프가 !top_side                8 / 12
//   Mid    비2차타워 & top_side                     14 / 14
//   Mid    비2차타워 & !top_side                    11 / 11
//   Bottom 타워 전멸                                 9 / 21
//   Bottom 2차타워                                  15 / 20
//   Bottom 1차타워 & nearest_enemy=Some             20 / 15
//   Bottom 1차타워 & nearest_enemy=None             15 / 20
